BASE=ROOT.parent/'Sem 1 Term 1/Writing Practice/Exam Prep/text'
source_blocks={}
for pn in range(1,6):
 raw=(BASE/f'paper{pn}.txt').read_bytes()
 try:text=raw.decode('utf-8')
 except UnicodeDecodeError:text=raw.decode('cp1252')
 matches=list(re.finditer(r'Q\.\s*(\d+)\.',text))
 source_blocks[pn]={int(m[1]):text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)].replace('\f','').strip().rstrip('*\n\r ') for i,m in enumerate(matches)}
def flat(s):return re.sub(r'\s+',' ',s).strip()
def source(p,n):
 b=source_blocks[p][n];m=re.search(r'\[\s*([\d.\s]+)\s*Marks\s*\]',b,re.I)
 assert m,(p,n)
 return flat(b[:m.start()]),float(m[1].replace(' ', '').replace('\n','').replace('\r','')),b[m.end():].strip(),flat(b)
def pastwrite(p,n,task,title,model,passage=None,target=None,**kw):
 prompt,marks,after,full=source(p,n)
 if task=='paraphrase' and passage is None:passage=flat(after)
 q=writing(f'wp-p{p}-q{n}',task,f'Paper {p}: {title}',prompt,model,pool='past',marks=marks,target=target,passage=passage,source=f'Past paper {p} Q{n}',originalMarks=marks,originalPrompt=full,**kw)
 q['notes']='Original past-paper wording and marks are retained. The upcoming exam uses the instructor’s new 50-mark format. '+q.get('notes','')
 past.append(q);return q
past_essays=[
'''Social media users and platforms should share responsibility for limiting rumours without suppressing legitimate disagreement. Rapid communication is valuable, but the ease of forwarding information can give unsupported claims an appearance of authority.

First, a rumour may reach many people before anyone checks its origin. Users can reduce this risk by pausing before sharing, checking the date and consulting the original source. A dramatic screenshot is not sufficient evidence simply because a trusted friend has forwarded it. Small acts of verification can interrupt careless repetition.

Second, platforms should make reliable context and correction easier to find. Clear reporting tools and visible explanations for moderation decisions can help users understand why a claim is disputed. Corrections should reach people who encountered the original post where practical.

Critics may fear that these measures will restrict expression. That concern supports transparent rules and an appeal process, rather than allowing every accusation to circulate without scrutiny. Disagreement should remain possible, while fabricated claims should not gain protection merely by being popular. Responsible sharing and accountable platform design can preserve useful communication while reducing the harm caused by unexamined rumours.''',
'''Social media services should combine user education with effective security measures to reduce cybercrime. These platforms support useful communication, but criminals can exploit trust, personal information and rapid sharing to deceive users.

First, ordinary precautions can reduce avoidable exposure. Users should verify unexpected requests through an independent channel and avoid sharing passwords or one-time codes. A message appearing to come from a familiar account may still be fraudulent. Teaching people to pause and check a request is more practical than assuming that they can recognise every technical trick.

Second, platforms must take responsibility for the systems they operate. Accessible reporting, account protection and clear warnings about suspicious activity can make abuse easier to detect and contain. A victim should have a usable route for seeking assistance.

Some argue that individuals alone should bear the consequences of careless online behaviour. Personal responsibility matters, but it cannot replace responsible service design. Criminals deliberately exploit predictable mistakes, and platforms are better placed to detect repeated patterns. A balanced approach therefore combines informed users with accountable providers. Social media can remain useful while its participants work together to make deception harder and recovery easier.''',
'''E-learning can improve academic achievement when it is combined with suitable teaching and reliable access. Its value depends on how it supports learning rather than on the mere presence of a digital platform.

First, recorded explanations and downloadable material allow learners to revisit difficult concepts. A student can pause an example, attempt the steps independently and return to the explanation where understanding breaks down. This flexibility can make revision more purposeful than repeatedly reading incomplete classroom notes.

Second, online tools can provide frequent practice and timely feedback. Short quizzes or draft reviews can reveal misunderstandings before a final assessment. Teachers can then respond to the difficulties actually shown by their students.

However, critics rightly point to unreliable connectivity, distraction and reduced personal contact. These problems can undermine achievement, particularly when institutions assume that every student has the same equipment. Downloadable resources, clear schedules and opportunities for discussion can reduce some of these barriers. E-learning should therefore complement thoughtful teaching rather than be treated as an automatic improvement. With equitable access and active engagement, it can strengthen understanding; without them, it may simply transfer existing difficulties onto a screen.''',
'''Governments should fund supportive care for terminally ill patients while respecting carefully established decisions about treatment. Financial pressure should not determine whether a person receives comfort, dignity and appropriate assistance. The question should therefore be approached through patient welfare rather than a simple choice between expenditure and death.

First, funded care can reduce the burden on families. A household facing prolonged illness may struggle to obtain nursing support, pain relief and clear advice. Public provision can make these services more accessible and prevent lack of money from becoming the decisive consideration. Support should address both the patient's needs and the practical demands placed on caregivers.

Second, humane care requires attention to individual wishes and clinical circumstances. Terminal illness and a vegetative state are not interchangeable descriptions. Decisions about treatment should involve appropriate expertise, careful communication and respect for the patient's expressed preferences. An essay should not assume that every case has the same prognosis or desired outcome.

Critics may argue that limited public resources should be directed only towards curable conditions. Resource allocation is a real challenge, but relief of suffering remains a legitimate purpose of healthcare. Proportionate supportive services can protect dignity without assuming that every possible intervention must continue indefinitely.

Government funding should therefore make meaningful care available while allowing difficult decisions to follow the relevant safeguards. Compassion is better served by informed choices and accessible support than by presenting vulnerable patients or their families with a financially forced alternative.''',
'''Conducting compulsory offline examinations after entirely online classes during lockdown was unfair where institutions failed to address students’ unequal circumstances. An assessment may be academically demanding, but it should also provide a reasonable opportunity for students to demonstrate learning.

First, online teaching did not guarantee equal preparation. Some students had quiet rooms, dependable devices and reliable connections; others struggled to join classes consistently. A common examination could therefore reflect differences in access as well as differences in understanding. Institutions needed to identify and respond to these barriers before deciding on an assessment format.

Second, travelling to an examination centre could create additional difficulty during a disrupted period. Students living far away or facing family responsibilities required clear notice and workable arrangements. A sudden change of mode could place burdens on those least able to absorb them. Fairness required consultation, accessible information and appropriate alternatives.

Supporters of offline examinations may argue that supervision improves confidence in independent work. That concern is reasonable. However, academic integrity can be addressed through suitable assessment design, oral follow-up or carefully organised alternatives. It does not justify ignoring access and travel difficulties.

Offline assessment was therefore defensible only when practical safeguards and adequate preparation accompanied it. Institutions should have matched their expectations with the learning conditions students actually experienced. The fairest response would preserve academic standards while ensuring that the method of assessment did not create avoidable disadvantages unrelated to the knowledge being tested.'''
]
for p,m in enumerate(past_essays,1):pastwrite(p,1,'essay',['Rumours and social media','Social media and cybercrime','E-learning achievement','Supportive care debate','Offline exams after online classes'][p-1],m,target=(150,200) if p<=3 else (200,250),notes='For upcoming Q1A, practise a 250-word essay. Historical contextual statements are reproduced from the question, not presented as current legal or medical advice.')
paraphrase_models=[
(1,2,'''Bangladesh, Bhutan, India, the Maldives, Nepal, Pakistan, Sri Lanka and Tibet are included in the source’s account of South Asia. The label is frequently employed to construct a geographical or strategic political grouping, expressing alliances within Asia and among communities abroad. It may also shape social classifications without directly referring to nationality. Rather than simply identifying a conventional area-studies object, the term frames an interconnected region whose economies, political relationships and histories can be examined together. Its role is nevertheless uncertain and potentially contradictory, so the category should not be accepted as having a single straightforward meaning.'''),
(1,3,'''During the 1930s, quantum entanglement became central to a heated disagreement involving Einstein, Bohr and Schrödinger over the basic character of the universe. For Einstein, reality had to exist in a definite form that could, in principle, be completely understood. Whether considering the moon or a light particle, he expected objects to possess specific characteristics discoverable by observation. By contrast, the emerging quantum account supported by Bohr, Schrödinger and others suggested unavoidable uncertainty. In that view, some features of a particle become determinate only when it is measured, rather than existing as fixed properties beforehand.'''),
(2,2,'''Printing without ink has recently drawn considerable interest as a less environmentally damaging technology and represents a major development in printing methods. The same environmental argument applies to writing. Conventional writing fluids include substances that can endanger people and the natural world. Moreover, marks made with ink usually remain on the page and cannot readily be removed. This permanence contributes to discarded paper and creates difficulties for protecting forests. An environmentally responsible substitute for ink is consequently worth investigating, so that the effects of writing, as well as those of printing, can be reduced.'''),
(2,3,'''An article that Frank Sinatra published in Time years ago taught me a useful lesson about singing. He suggested treating the microphone as though it were a loved one in order to regulate the voice precisely. A gentle, affectionate phrase calls for bringing it nearer, whereas a forceful passage requires moving it farther away. Learning to manage these adjustments depends on practical experience rather than merely knowing the advice. The skilled singer develops control by discovering when closeness or distance best serves the expression of the performance.'''),
(3,2,'''Research into pollution in rivers and other surface sources, underground supplies and rainfall has repeatedly identified substantial metal concentrations. This review examines cadmium, lead, mercury and arsenic in sub-Saharan African waters because these substances are poisonous and affect both human health and ecosystems. Exposure is associated with serious illnesses, including lead poisoning, mercury poisoning and Itai Itai disease. The article considers whether communities can obtain enough safe drinking water, where metal pollution originates and how extensive it is. It also examines techniques for detecting these contaminants and the effects of consuming affected water, bringing together questions of supply, measurement and harm.'''),
(3,3,'''ChatGPT introduced a broad public to the abilities of large language models. Such systems can produce readable academic essays, condense scientific articles, generate useful programs and answer questions at a level sufficient for medical examinations. Their research summaries have even made it difficult for scientists to recognise computer authorship. The report also warned that these capabilities could simplify the creation of unwanted messages, ransomware and other harmful material. Although the developer had introduced restrictions, users were already discovering ways to evade them. Nature therefore outlined principles for using these tools. The report stressed that scientific progress depends on honest authorship, accurate claims and openness about research procedures. These foundations must remain central even when automated writing becomes convincing and widely available.'''),
(4,2,'''Evening begins as the sun descends and daylight gives way to night. At this moment, the natural world takes on a renewed brilliance. The sun resembles a golden circle, while a striking range of colours spreads across the western heavens. The sky and land appear washed in many shades. Light from the sinking sun touches rivers, ponds and treetops, making the distant western edge especially attractive. A reddish glow fills the sky and changes the appearance of surrounding objects. Beneath that light, the river’s small waves seem purple. As the sun finally passes out of view, the red colouring gradually fades. Darkness then extends over the landscape. People tending cattle lead their animals home, and birds make their way towards their nests. Eventually, only a few stars remain visible in the western sky. Watching this transition from vivid evening light to darkness offers a pleasing experience, bringing together changing colours, movement and the quiet return of living creatures to shelter.'''),
(5,2,'''The natural world makes life possible through the connections among its living and non-living elements. People, animals and plants depend on this system for air, light, land, water and other essentials. Clearing forests has contributed greatly to rising global temperatures and damage to the environment. Industrial activity adds further pressure by consuming too many resources and releasing dangerous chemicals and gases. Reducing harm now requires using fewer materials, putting existing items to further use and turning discarded products into new ones. Cooperation across countries is needed to ease these pressures and recover ecological stability. Protecting the environment carefully has therefore become an urgent shared responsibility if its essential systems are to survive continuing threats.''')]
for p,n,m in paraphrase_models:
 q=pastwrite(p,n,'paraphrase','Paraphrase '+str(n),m)
 # Approximate source length; attribution strings are not part of the length target.
 plen=len(re.sub(r'\([^)]*\)\s*$','',q['passage']).split());q['wordTarget']={'min':round(plen*.9),'max':round(plen*1.1)}
